// The reference: the plain loop, pipelined.  Do not edit this file -- the
// build synthesizes it beside yours (dot.cpp) so you can compare the two.
//
// One multiply and one add per iteration, one sample of a and of b read per
// iteration: II = 1, one sample per clock cycle.
#include "dot.h"

int dot(const short a[N], const short b[N]) {
#pragma HLS INTERFACE mode=ap_memory port=a storage_type=ram_1p
#pragma HLS INTERFACE mode=ap_memory port=b storage_type=ram_1p

    int sum = 0;
    dot_loop: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        sum += a[i] * b[i];
    }
    return sum;
}
